function feedback({ response }) {
  if (!Array.isArray(response?.definition?.fields) || !Array.isArray(response?.answers))
    throw Error("Expected the complete Typeform response");
  const read = (title, type, required) => {
    const matches = response.definition.fields.filter((x) => x?.title === title);
    if (
      matches.length !== 1 ||
      !matches[0].id ||
      response.definition.fields.filter((x) => x.id === matches[0].id).length !== 1
    )
      throw Error("Expected one question titled " + title);
    const answers = response.answers.filter((x) => x?.field?.id === matches[0].id);
    if (!answers.length && !required) return "";
    if (answers.length !== 1 || answers[0].type !== type)
      throw Error("Invalid answer for " + title);
    const v = answers[0][type];
    if (
      type === "number"
        ? typeof v !== "number" || !Number.isFinite(v)
        : typeof v !== "string" || (required && !v.trim())
    )
      throw Error("Invalid answer for " + title);
    return v;
  };
  const fields = {
    Name: read("What is your name?", "text", true),
    Email: read("What is your email address?", "email", false),
    Score: read("What score would you like to give?", "number", true),
    Description: read("Anything else you want to share?", "text", false),
  };
  return { fields, records: [{ fields }] };
}

if ($json.event_type !== "form_response") throw Error("Expected a completed Typeform response");
return { json: feedback({ response: $json.form_response }).fields };

function confirm({ records, fields }) {
  if (
    !Array.isArray(records) ||
    records.length !== 1 ||
    typeof records[0]?.id !== "string" ||
    !records[0].id
  )
    throw Error("Airtable did not confirm one record");
  const f = records[0].fields;
  if (
    !f ||
    f.Score !== fields.Score ||
    f.Name !== fields.Name ||
    (f.Email ?? "") !== fields.Email ||
    (f.Description ?? "") !== fields.Description
  )
    throw Error("Airtable record differs from submitted feedback");
  const name = `[${f.Score}] ${f.Name}`,
    description = `Name: ${f.Name}\nEmail: ${f.Email ?? ""}\nScore: ${f.Score}\nDescription: ${f.Description ?? ""}`;
  return { low: f.Score < 7, name, description };
}

const items = $input.all();
return [
  {
    json: confirm({
      records: items.map((x) => x.json),
      fields: $("Read the feedback answers").first().json,
    }),
  },
];
